import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        List<Integer> numbers = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            String t = sc.next();
            if (t.equals("null")) {
                numbers.add(null);
            } else {
                numbers.add(Integer.parseInt(t));
            }
        }

        System.out.println(numbers);

        try {
            int sum = 0;
            for (int n : numbers) {
                sum += n;
            }
            System.out.println("intで回すと " + sum);
        } catch (NullPointerException e) {
            System.out.println("intで回すと NPE");
        }

        int safe = 0;
        int nullCount = 0;
        for (Integer n : numbers) {
            if (n == null) {
                nullCount++;
            } else {
                safe += n;
            }
        }
        System.out.println("安全な合計 " + safe);
        System.out.println("nullの個数 " + nullCount);
    }
}

