public class Main {
    // 呼ぶたびに同じ中身の新しいリストを返す
    static List<Integer> make(int[] src) {
        List<Integer> list = new ArrayList<>();
        for (int n : src) {
            list.add(n);
        }
        return list;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        int[] src = new int[k];
        for (int i = 0; i < k; i++) {
            src[i] = sc.nextInt();
        }
        int v = sc.nextInt();

        System.out.println("位置0 " + make(src).remove(0));
        System.out.println("値v " + make(src).remove(Integer.valueOf(v)));

        List<Integer> back = make(src);
        for (int i = back.size() - 1; i >= 0; i--) {
            if (back.get(i) == v) {
                back.remove(i);
            }
        }
        System.out.println("後ろから " + back);

        List<Integer> front = make(src);
        for (int i = 0; i < front.size(); i++) {
            if (front.get(i) == v) {
                front.remove(i);
            }
        }
        System.out.println("前から " + front);

