import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        String[] arr = new String[k];
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < k; i++) {
            arr[i] = sc.next();
            if (seen.add(arr[i])) {
                System.out.println("初 " + arr[i]);
            } else {
                System.out.println("既 " + arr[i]);
            }
        }

        System.out.println("種類 " + seen.size());

        List<String> fixedSize = Arrays.asList(arr);
        fixedSize.set(0, "Z");
        System.out.println("asList set " + fixedSize);

        try {
            fixedSize.add("Y");
        } catch (UnsupportedOperationException e) {
            System.out.println("asList add NG");
        }

        List<String> copy = new ArrayList<>(fixedSize);
        copy.add("W");
        System.out.println("詰め替え " + copy);
    }
}

